void main() {
  // CONST - Nilai harus sudah diketahui saat kompilasi
  const String namaApp = "Belajar Dart";
  const int versi = 1;
  const double pi = 3.14159;

  // FINAL - Nilai bisa ditentukan saat runtime
  final DateTime waktuSekarang = DateTime.now(); // Runtime value
  final String pesanWaktu = "Program dijalankan pada: $waktuSekarang";

  // Keduanya bisa digunakan saat runtime
  print("=== CONST (sudah ditentukan saat kompilasi) ===");
  print("Nama App: $namaApp");
  print("Versi: $versi");
  print("PI: $pi");

  print("\n=== FINAL (ditentukan saat runtime) ===");
  print(pesanWaktu);

  // PERBEDAAN UTAMA:
  print("\n=== PERBEDAAN ===");

  // Ini TIDAK BISA dengan const karena DateTime.now() adalah runtime value
  // const DateTime constTime = DateTime.now(); // ERROR!

  // Tapi ini BISA dengan final
  final DateTime finalTime = DateTime.now(); // OK!

  print("Final time: $finalTime");

  // Keduanya tidak bisa diubah setelah diinisialisasi
  // namaApp = "App Baru"; // ERROR!
  // waktuSekarang = DateTime.now(); // ERROR!
}

void main(){
  print("=== BELAJAR MAP DI DART ===\n");

  // 1. APA ITU MAP?
  print("1. MAP adalah koleksi key-value pairs");
  print("   Setiap key harus unik, value bisa duplikat\n");

  // 2. CARA MEMBUAT MAP
  print("2. CARA MEMBUAT MAP:");

  // Cara 1: Map literal {}
  Map<String, int> umur = {
    'Andi': 25,
    'Budi': 30,
    'Citra': 22
  };
  print("   Map literal: $umur");

  // Cara 2: Map constructor
  Map<String, String> kota = Map();
  kota['Jakarta'] = 'DKI Jakarta';
  kota['Surabaya'] = 'Jawa Timur';
  kota['Medan'] = 'Sumatera Utara';
  print("   Map constructor: $kota");

  // Cara 3: Map.from()
  Map<String, dynamic> siswa = Map.from({
    'nama': 'Doni',
    'umur': 20,
    'kelas': '12A',
    'aktif': true
  });
  print("   Map.from(): $siswa");

  // Cara 4: Map kosong
  Map<String, int> nilai = <String, int>{};
  print("   Map kosong: $nilai\n");

  // 3. OPERASI DASAR MAP
  print("3. OPERASI DASAR MAP:");
  Map<String, int> skor = {
    'Matematika': 85,
    'Fisika': 90,
    'Kimia': 78
  };

  // Menambah/mengubah value
  skor['Biologi'] = 88;
  print("   Setelah tambah Biologi: $skor");

  skor['Matematika'] = 95; // mengubah value yang sudah ada
  print("   Setelah ubah Matematika: $skor");

  // Mengakses value
  print("   Nilai Fisika: ${skor['Fisika']}");
  print("   Nilai Sejarah: ${skor['Sejarah']}"); // null karena tidak ada

  // Mengecek apakah key ada
  print("   Apakah ada Kimia? ${skor.containsKey('Kimia')}");
  print("   Apakah ada Sejarah? ${skor.containsKey('Sejarah')}");

  // Mengecek apakah value ada
  print("   Apakah ada nilai 90? ${skor.containsValue(90)}");
  print("   Apakah ada nilai 100? ${skor.containsValue(100)}");

  // Menghapus entry
  skor.remove('Kimia');
  print("   Setelah hapus Kimia: $skor");

  // Panjang map
  print("   Jumlah mata pelajaran: ${skor.length}");
  print("   Apakah kosong? ${skor.isEmpty}\n");

  // 4. MENGAKSES KEYS DAN VALUES
  print("4. MENGAKSES KEYS DAN VALUES:");
  Map<String, String> negara = {
    'ID': 'Indonesia',
    'MY': 'Malaysia', 
    'SG': 'Singapura',
    'TH': 'Thailand'
  };

  print("   Map negara: $negara");
  print("   Semua keys: ${negara.keys}");
  print("   Semua values: ${negara.values}");
  print("   Entries: ${negara.entries}\n");

  // 5. ITERASI MAP
  print("5. CARA MENGITERASI MAP:");
  Map<String, double> harga = {
    'Apel': 15000.0,
    'Jeruk': 12000.0,
    'Mangga': 20000.0,
    'Pisang': 8000.0
  };

  print("   Menggunakan forEach (key, value):");
  harga.forEach((key, value) {
    print("     $key: Rp ${value.toStringAsFixed(0)}");
  });

  print("   Menggunakan for-in dengan entries:");
  for (MapEntry<String, double> entry in harga.entries) {
    print("     ${entry.key}: Rp ${entry.value.toStringAsFixed(0)}");
  }

  print("   Menggunakan for-in dengan keys:");
  for (String buah in harga.keys) {
    print("     $buah: Rp ${harga[buah]!.toStringAsFixed(0)}");
  }

  // 6. OPERASI LANJUTAN MAP
  print("\n6. OPERASI LANJUTAN MAP:");
  Map<String, int> inventori = {
    'Laptop': 10,
    'Mouse': 25,
    'Keyboard': 15,
    'Monitor': 8
  };

  // putIfAbsent - tambah jika key belum ada
  inventori.putIfAbsent('Speaker', () => 12);
  print("   Setelah putIfAbsent Speaker: $inventori");

  inventori.putIfAbsent('Laptop', () => 99); // tidak akan mengubah karena Laptop sudah ada
  print("   putIfAbsent Laptop (tidak berubah): $inventori");

  // update - ubah value jika key ada
  inventori.update('Mouse', (value) => value + 5);
  print("   Setelah update Mouse +5: $inventori");

  // updateAll - ubah semua values
  inventori.updateAll((key, value) => value * 2);
  print("   Setelah updateAll x2: $inventori");

  // clear - hapus semua
  Map<String, int> temp = Map.from(inventori);
  temp.clear();
  print("   Setelah clear temp: $temp\n");

  // 7. MAP DENGAN TIPE DATA KOMPLEKS
  print("7. MAP DENGAN TIPE DATA KOMPLEKS:");
  Map<String, List<String>> hobi = {
    'Andi': ['Membaca', 'Menulis', 'Coding'],
    'Budi': ['Olahraga', 'Gaming'],
    'Citra': ['Menggambar', 'Musik', 'Traveling', 'Photography']
  };

  print("   Map hobi:");
  hobi.forEach((nama, daftarHobi) {
    print("     $nama: $daftarHobi");
  });

  // Mengakses elemen dalam List di Map
  print("   Hobi pertama Andi: ${hobi['Andi']![0]}");
  print("   Jumlah hobi Citra: ${hobi['Citra']!.length}\n");

  // 8. MAP BERSARANG (NESTED MAP)
  print("8. MAP BERSARANG:");
  Map<String, Map<String, dynamic>> mahasiswa = {
    'M001': {
      'nama': 'Ahmad',
      'jurusan': 'Informatika',
      'semester': 6,
      'ipk': 3.75
    },
    'M002': {
      'nama': 'Siti',
      'jurusan': 'Sistem Informasi', 
      'semester': 4,
      'ipk': 3.85
    }
  };

  print("   Data mahasiswa:");
  mahasiswa.forEach((nim, data) {
    print("     NIM: $nim");
    print("       Nama: ${data['nama']}");
    print("       Jurusan: ${data['jurusan']}");
    print("       Semester: ${data['semester']}");
    print("       IPK: ${data['ipk']}");
  });

  // 9. KONVERSI DAN TRANSFORMASI
  print("\n9. KONVERSI DAN TRANSFORMASI:");
  Map<String, int> angka = {'satu': 1, 'dua': 2, 'tiga': 3};

  // Map ke List
  List<String> keys = angka.keys.toList();
  List<int> values = angka.values.toList();
  print("   Keys sebagai List: $keys");
  print("   Values sebagai List: $values");

  // Transform values
  Map<String, int> angkaKali2 = angka.map((key, value) => MapEntry(key, value * 2));
  print("   Angka dikali 2: $angkaKali2");

  // Filter map
  Map<String, int> angkaGenap = angka.map((key, value) => MapEntry(key, value))
      .cast<String, int>();
  Map<String, int> filtered = Map.fromEntries(
      angkaKali2.entries.where((entry) => entry.value > 4)
  );
  print("   Filter nilai > 4: $filtered");

  // 10. CONTOH PRAKTIS
  print("\n10. CONTOH PRAKTIS - SISTEM PENILAIAN:");
  Map<String, Map<String, int>> nilaiSiswa = {
    'Andi': {'Matematika': 85, 'IPA': 90, 'IPS': 78},
    'Budi': {'Matematika': 75, 'IPA': 82, 'IPS': 88},
    'Citra': {'Matematika': 95, 'IPA': 87, 'IPS': 92}
  };

  print("   Laporan Nilai:");
  nilaiSiswa.forEach((siswa, mapel) {
    int total = mapel.values.reduce((a, b) => a + b);
    double rata = total / mapel.length;
    print("     $siswa - Total: $total, Rata-rata: ${rata.toStringAsFixed(1)}");
  });

  // 11. TIPS DAN BEST PRACTICES
  print("\n11. TIPS MAP:");
  print("   - Gunakan Map untuk relasi key-value");
  print("   - Key harus unik, value boleh duplikat");
  print("   - Gunakan containsKey() sebelum mengakses value");
  print("   - Map tidak memiliki urutan yang pasti (kecuali LinkedHashMap)");
  print("   - Gunakan Map<String, dynamic> untuk data yang fleksibel");
}

void main(){
  Set<int> set = new Set.from([1,5,1,7,1,7]);
  print(set);

  var set2 = {2,12,4,2,2,6};
  set2.add(8);
  set2.addAll([1,2,3,4,5]);
  print(set2);
}

void main(){
  print("=== BELAJAR SET DI DART ===\n");

  // 1. APA ITU SET?
  print("1. SET adalah koleksi yang tidak mengijinkan duplikasi");
  print("   Set otomatis menghilangkan elemen yang sama\n");

  // 2. CARA MEMBUAT SET
  print("2. CARA MEMBUAT SET:");

  // Cara 1: Menggunakan Set.from()
  Set<int> set1 = Set.from([1,5,1,7,1,7]);
  print("   Set dari list: $set1");

  // Cara 2: Menggunakan literal {}
  var set2 = {2,12,4,2,2,6};
  print("   Set literal: $set2");

  // Cara 3: Set kosong
  Set<String> set3 = <String>{};
  print("   Set kosong: $set3");

  // Cara 4: Set dengan tipe data
  Set<String> buah = {'apel', 'jeruk', 'mangga', 'apel'};
  print("   Set buah: $buah\n");

  // 3. OPERASI DASAR SET
  print("3. OPERASI DASAR SET:");
  Set<int> angka = {1, 2, 3, 4, 5};

  // Menambah elemen
  angka.add(6);
  print("   Setelah add(6): $angka");

  // Menambah beberapa elemen
  angka.addAll([7, 8, 9, 1]); // 1 tidak akan ditambah karena sudah ada
  print("   Setelah addAll([7,8,9,1]): $angka");

  // Menghapus elemen
  angka.remove(5);
  print("   Setelah remove(5): $angka");

  // Mengecek apakah elemen ada
  print("   Apakah 3 ada? ${angka.contains(3)}");
  print("   Apakah 10 ada? ${angka.contains(10)}");

  // Panjang set
  print("   Jumlah elemen: ${angka.length}");
  print("   Apakah kosong? ${angka.isEmpty}\n");

  // 4. OPERASI SET (UNION, INTERSECTION, DIFFERENCE)
  print("4. OPERASI MATEMATIKA SET:");
  Set<int> setA = {1, 2, 3, 4, 5};
  Set<int> setB = {4, 5, 6, 7, 8};

  print("   Set A: $setA");
  print("   Set B: $setB");

  // Union (gabungan)
  Set<int> union = setA.union(setB);
  print("   Union A ∪ B: $union");

  // Intersection (irisan)
  Set<int> intersection = setA.intersection(setB);
  print("   Intersection A ∩ B: $intersection");

  // Difference (selisih)
  Set<int> difference = setA.difference(setB);
  print("   Difference A - B: $difference\n");

  // 5. ITERASI SET
  print("5. CARA MENGITERASI SET:");
  Set<String> warna = {'merah', 'biru', 'hijau', 'kuning'};

  print("   Menggunakan for-in:");
  for (String w in warna) {
    print("     - $w");
  }

  print("   Menggunakan forEach:");
  warna.forEach((w) => print("     * $w"));

  // 6. KONVERSI SET
  print("\n6. KONVERSI SET:");
  Set<int> setAngka = {3, 1, 4, 1, 5, 9, 2, 6};

  // Set ke List
  List<int> listDariSet = setAngka.toList();
  print("   Set ke List: $listDariSet");

  // List ke Set (menghilangkan duplikasi)
  List<int> listDuplikat = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4];
  Set<int> setDariList = listDuplikat.toSet();
  print("   List dengan duplikasi: $listDuplikat");
  print("   Setelah jadi Set: $setDariList");

  // 7. CONTOH PRAKTIS
  print("\n7. CONTOH PRAKTIS - MENGHILANGKAN DUPLIKASI:");
  List<String> daftarNama = ['Andi', 'Budi', 'Andi', 'Citra', 'Budi', 'Doni'];
  print("   Daftar nama asli: $daftarNama");

  Set<String> namaUnik = daftarNama.toSet();
  print("   Nama unik: $namaUnik");
  print("   Jumlah nama unik: ${namaUnik.length}");

  // 8. SET VS LIST
  print("\n8. PERBEDAAN SET VS LIST:");
  print("   LIST: [1,2,2,3] - Mengijinkan duplikasi, ada urutan/index");
  print("   SET:  {1,2,3}   - Tidak ada duplikasi, tidak ada urutan/index");

  List<int> list = [1, 2, 2, 3];
  Set<int> set = {1, 2, 2, 3};
  print("   List: $list (length: ${list.length})");
  print("   Set:  $set (length: ${set.length})");
}
